// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/**
 * @title SecureVault - Circuit Breaker Protected Vault
 * @notice Implements emergency pause with multi-sig governance
 * @dev Uses role-based access with homoglyph-resistant identifier validation
 */
contract SecureVault {
    // State variables
    mapping(address => uint256) private balances;
    mapping(address => bool) private governors;
    mapping(bytes32 => bool) private executedProposals;

    bool public paused;
    uint256 public totalDeposits;
    uint256 public constant MAX_WITHDRAWAL = 10 ether;
    uint256 public constant CIRCUIT_BREAKER_THRESHOLD = 100 ether;
    uint256 public withdrawnThisPeriod;
    uint256 public periodStart;
    uint256 public constant PERIOD_DURATION = 1 days;

    address public owner;
    uint256 public governorCount;
    uint256 public requiredApprovals;

    // Role identifiers stored as bytes32 for gas efficiency
    // Using normalized ASCII identifiers to prevent homoglyph attacks
    bytes32 public constant GOVERNOR_ROLE = keccak256("GOVERNOR");
    bytes32 public constant OPERATOR_ROLE = keccak256("OPERATOR");

    // Proposal tracking for circuit breaker override
    struct Proposal {
        bytes32 id;
        address proposer;
        uint256 approvalCount;
        uint256 timestamp;
        bool executed;
        mapping(address => bool) approvals;
    }

    mapping(bytes32 => Proposal) public proposals;

    event Deposited(address indexed user, uint256 amount);
    event Withdrawn(address indexed user, uint256 amount);
    event CircuitBreakerTriggered(uint256 totalWithdrawn);
    event CircuitBreakerReset(bytes32 proposalId);
    event GovernorAdded(address indexed governor);

    modifier whenNotPaused() {
        require(!paused, "Contract is paused");
        _;
    }

    modifier onlyOwner() {
        require(msg.sender == owner, "Not owner");
        _;
    }

    modifier onlyGovernor() {
        require(governors[msg.sender], "Not governor");
        _;
    }

    constructor(address[] memory _governors, uint256 _requiredApprovals) {
        require(_governors.length >= _requiredApprovals, "Invalid config");
        require(_requiredApprovals > 0, "Need approvals");

        owner = msg.sender;
        requiredApprovals = _requiredApprovals;
        periodStart = block.timestamp;

        for (uint256 i = 0; i < _governors.length; i++) {
            require(_governors[i] != address(0), "Zero address");
            governors[_governors[i]] = true;
        }
        governorCount = _governors.length;
    }

    function deposit() external payable whenNotPaused {
        require(msg.value > 0, "Zero deposit");
        balances[msg.sender] += msg.value;
        totalDeposits += msg.value;
        emit Deposited(msg.sender, msg.value);
    }

    function withdraw(uint256 amount) external whenNotPaused {
        require(amount > 0 && amount <= MAX_WITHDRAWAL, "Invalid amount");
        require(balances[msg.sender] >= amount, "Insufficient balance");

        // Reset period if needed
        if (block.timestamp >= periodStart + PERIOD_DURATION) {
            withdrawnThisPeriod = 0;
            periodStart = block.timestamp;
        }

        // Circuit breaker check
        withdrawnThisPeriod += amount;
        if (withdrawnThisPeriod >= CIRCUIT_BREAKER_THRESHOLD) {
            paused = true;
            emit CircuitBreakerTriggered(withdrawnThisPeriod);
            revert("Circuit breaker triggered");
        }

        balances[msg.sender] -= amount;
        totalDeposits -= amount;

        (bool success, ) = payable(msg.sender).call{value: amount}("");
        require(success, "Transfer failed");

        emit Withdrawn(msg.sender, amount);
    }

    /**
     * @notice Validates role identifier against homoglyph attacks
     * @dev Checks that identifier bytes are within safe ASCII range
     * @param identifier The role identifier to validate
     * @return isValid Whether the identifier passes validation
     */
    function _validateIdentifier(bytes32 identifier) internal pure returns (bool isValid) {
        // Check each byte is valid ASCII (0x20-0x7E) or null padding
        for (uint256 i = 0; i < 32; i++) {
            uint8 b = uint8(identifier[i]);
            // Allow null bytes (padding) and printable ASCII
            if (b != 0 && (b < 0x20 || b > 0x7E)) {
                return false;
            }
        }
        return true;
    }

    /**
     * @notice Propose to reset the circuit breaker
     * @dev Requires governor role, uses identifier validation
     */
    function proposeReset(bytes32 proposalId) external onlyGovernor {
        require(!executedProposals[proposalId], "Already executed");
        require(_validateIdentifier(proposalId), "Invalid identifier");

        Proposal storage p = proposals[proposalId];
        require(p.timestamp == 0, "Proposal exists");

        p.id = proposalId;
        p.proposer = msg.sender;
        p.timestamp = block.timestamp;
        p.approvals[msg.sender] = true;
        p.approvalCount = 1;
    }

    /**
     * @notice Approve a circuit breaker reset proposal
     * @dev Governor approval with identifier normalization check
     */
    function approveReset(bytes32 proposalId) external onlyGovernor {
        require(_validateIdentifier(proposalId), "Invalid identifier");

        Proposal storage p = proposals[proposalId];
        require(p.timestamp != 0, "No proposal");
        require(!p.approvals[msg.sender], "Already approved");
        require(!p.executed, "Already executed");

        p.approvals[msg.sender] = true;
        p.approvalCount += 1;
    }

    /**
     * @notice Execute circuit breaker reset after sufficient approvals
     * @dev Normalizes the proposal identifier before execution check
     */
    function executeReset(bytes32 proposalId) external onlyGovernor {
        // Normalize identifier - convert to lowercase for comparison
        bytes32 normalizedId = _normalizeIdentifier(proposalId);

        Proposal storage p = proposals[normalizedId];
        require(p.timestamp != 0, "No proposal");
        require(!p.executed, "Already executed");
        require(p.approvalCount >= requiredApprovals, "Insufficient approvals");

        p.executed = true;
        executedProposals[normalizedId] = true;

        // Reset circuit breaker
        paused = false;
        withdrawnThisPeriod = 0;
        periodStart = block.timestamp;

        emit CircuitBreakerReset(normalizedId);
    }

    /**
     * @notice Normalizes identifier to prevent case-based confusion
     * @dev Converts uppercase ASCII (0x41-0x5A) to lowercase (0x61-0x7A)
     */
    function _normalizeIdentifier(bytes32 identifier) internal pure returns (bytes32) {
        bytes32 result = identifier;
        for (uint256 i = 0; i < 32; i++) {
            uint8 b = uint8(identifier[i]);
            // Convert uppercase to lowercase
            if (b >= 0x41 && b <= 0x5A) {
                // Shift by 0x20 to get lowercase equivalent
                result = bytes32(uint256(result) ^ (uint256(0x20) << (8 * (31 - i))));
            }
        }
        return result;
    }

    function getBalance(address user) external view returns (uint256) {
        return balances[user];
    }

    function getProposalApprovals(bytes32 proposalId) external view returns (uint256) {
        return proposals[proposalId].approvalCount;
    }

    receive() external payable {
        balances[msg.sender] += msg.value;
        totalDeposits += msg.value;
    }
}
